import strawberry
from strawberry.file_uploads import Upload
from strawberry.types import Info

@strawberry.type
class LabUploadPayload:
    patient_record_id: int
    report_name: str
    success: bool

@strawberry.type
class Mutation:
    @strawberry.mutation
    async def upload_patient_lab_result(
        self,
        info: Info,
        patient_record_id: int,
        report: Upload
    ) -> LabUploadPayload:
        physician = info.context.get("physician_user")
        if not physician:
            raise Exception("Physician authentication required")

        ehr_store = info.context["ehr_storage"]
        has_care_relationship = await ehr_store.verify_care_team(
            record_id=patient_record_id,
            physician_id=physician.id
        )
        if not has_care_relationship:
            raise Exception("Access denied: You are not on the care team for this patient")

        file_bytes = await report.read()
        await ehr_store.append_lab_attachment(
            record_id=patient_record_id,
            filename=report.filename,
            content=file_bytes
        )

        return LabUploadPayload(
            patient_record_id=patient_record_id,
            report_name=report.filename,
            success=True
        )
